<?php
require_once __DIR__.'/../config/auth.php';require_admin();if(isset($_GET['delete'])){$s=db()->prepare("UPDATE drinks SET active=0 WHERE id=?");$s->execute([(int)$_GET['delete']]);header('Location:drinks.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']);$desc=trim($_POST['description']);$price=(float)$_POST['price'];$sort=(int)$_POST['sort_order'];$active=isset($_POST['active'])?1:0;if($id){$s=db()->prepare("UPDATE drinks SET name=?,description=?,price=?,sort_order=?,active=? WHERE id=?");$s->execute([$name,$desc,$price,$sort,$active,$id]);}else{$s=db()->prepare("INSERT INTO drinks(name,description,price,sort_order,active) VALUES(?,?,?,?,?)");$s->execute([$name,$desc,$price,$sort,$active]);}header('Location:drinks.php');exit;}$edit=null;if(isset($_GET['edit'])){$s=db()->prepare("SELECT * FROM drinks WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$drinks=db()->query("SELECT * FROM drinks ORDER BY active DESC,sort_order,name")->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Drinks</title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin-shell"><header class="admin-header"><div class="container nav"><div class="logo">COFFEE<span>ADMIN</span></div><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="drinks.php">Drinks</a><a href="milk.php">Milk Options</a><a href="completed.php">Completed Orders</a><a href="../kitchen/">Kitchen</a></nav></div></header><main class="container admin-main"><div class="panel"><h2><?=$edit?'Edit Drink':'Add Drink'?></h2><form method="post"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="grid-2"><div><div class="form-row"><label>Name</label><input name="name" required value="<?=htmlspecialchars($edit['name']??'')?>"></div><div class="form-row"><label>Description</label><textarea name="description" rows="5"><?=htmlspecialchars($edit['description']??'')?></textarea></div></div><div><div class="form-row"><label>Price</label><input type="number" step=".01" name="price" required value="<?=htmlspecialchars($edit['price']??'0.00')?>"></div><div class="form-row"><label>Display Order</label><input type="number" name="sort_order" value="<?=htmlspecialchars($edit['sort_order']??'0')?>"></div><div class="form-row"><label><input type="checkbox" name="active" <?=(!isset($edit)||$edit['active'])?'checked':''?> style="width:auto"> Active</label></div></div></div><button class="btn btn-yellow">SAVE DRINK</button><?php if($edit):?> <a class="btn btn-light" href="drinks.php">Cancel</a><?php endif;?></form></div><div class="panel"><h2>Drinks</h2><table class="table"><tr><th>Name</th><th>Description</th><th>Price</th><th>Status</th><th></th></tr><?php foreach($drinks as $d):?><tr><td><b><?=htmlspecialchars($d['name'])?></b></td><td><?=nl2br(htmlspecialchars($d['description']))?></td><td>$<?=number_format($d['price'],2)?></td><td><?=$d['active']?'Active':'Hidden'?></td><td class="actions"><a class="btn btn-light" href="?edit=<?=$d['id']?>">EDIT</a><?php if($d['active']):?><a class="btn btn-danger" href="?delete=<?=$d['id']?>" onclick="return confirm('Hide this drink?')">HIDE</a><?php endif;?></td></tr><?php endforeach;?></table></div></main><footer class="admin-footer"><div class="container admin-footer-inner"><div class="admin-footer-name">COFFEE <span>ADMIN</span></div><div class="admin-footer-links"><a href="password.php">Change Password</a><a href="logout.php">Log out</a></div></div></footer></body></html>
